def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    sorted_nums = sorted(set(nums))
    runs = []
    i = 0
    n = len(sorted_nums)

    while i < n:
        j = i
        while j + 1 < n and sorted_nums[j+1] == sorted_nums[j] + 1:
            j += 1
        runs.append((sorted_nums[i], sorted_nums[j]))
        i = j + 1

    parts = []
    for start, end in runs:
        if end - start >= 2:
            parts.append(f"{start}..{end}")
        else:
            parts.extend(str(x) for x in range(start, end + 1))

    return ",".join(parts)
